from .ranges import parse_header


def _range_error(length):
    return (416, {'Content-Length': '0',
                  'Content-Range': f'bytes */{length}'}, b'')


def serve(data, range_header=None):
    length = len(data)
    if range_header is None:
        return 200, {'Content-Length': str(length)}, data

    parsed = parse_header(range_header)
    if parsed is None or length == 0:
        return _range_error(length)

    if parsed[0] == 'suffix':
        n = parsed[1]
        if n == 0:
            return _range_error(length)
        start = max(0, length - n)
        end = length - 1
    else:
        start, end = parsed[1], parsed[2]
        if end is not None and end < start:
            return _range_error(length)
        if end is None:
            end = length - 1
        if start >= length:
            return _range_error(length)
        # Clamp end past EOF.
        if end >= length:
            end = length - 1

    body = data[start:end + 1]
    return (206, {'Content-Length': str(len(body)),
                  'Content-Range': f'bytes {start}-{end}/{length}'}, body)
